{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "IAM policy attached directly to user instead of group or role",
      "resource": "aws_iam_user_policy_attachment.privesc19-UpdateExistingGlueDevEndpoint-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching policies directly to IAM users violates the principle of least privilege and complicates access management. It increases the risk of inadvertently granting excessive privileges and makes auditing difficult compared to using groups or roles."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc19-UpdateExistingGlueDevEndpoint-group" {
  name = "privesc19-UpdateExistingGlueDevEndpoint-group"
}

resource "aws_iam_group_membership" "privesc19-UpdateExistingGlueDevEndpoint-user-membership" {
  name = "privesc19-UpdateExistingGlueDevEndpoint-user-membership"
  group = aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-group.name
  users = [aws_iam_user.privesc19-UpdateExistingGlueDevEndpoint-user.name]
}

resource "aws_iam_group_policy_attachment" "privesc19-UpdateExistingGlueDevEndpoint-group-attach-policy" {
  group      = aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-group.name
  policy_arn = aws_iam_policy.privesc19-UpdateExistingGlueDevEndpoint.arn
}",
  "fix_summary": "Replaced the direct user policy attachment with an IAM group. Created a new group, added the existing user to this group via membership, and attached the policy to the group instead of the user to adhere to best practices for identity-based access control."
}
